// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Votes.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/governance/Governor.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorSettings.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorCountingSimple.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorVotes.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorVotesQuorumFraction.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorTimelockControl.sol";
import "@openzeppelin/contracts/governance/TimelockController.sol";
import "@openzeppelin/contracts/governance/utils/IVotes.sol";


/**
 * @title GovernanceToken
 * @author Your Name
 * @notice An ERC20 token with voting and checkpointing capabilities (ERC20Votes),
 * gasless approvals (ERC20Permit), pausable transfers, and role-based access control.
 * This token is intended to be used as the governance token for a DAO.
 *
 * The deployer receives the initial supply and is granted the DEFAULT_ADMIN_ROLE and PAUSER_ROLE.
 * The PAUSER_ROLE can pause and unpause token transfers, which can be useful during
 * emergencies. The DEFAULT_ADMIN_ROLE can manage roles. It is recommended to transfer
or renounce these roles to a multisig or the DAO itself after setup.
 *
 * To participate in governance, token holders MUST delegate their voting power to
 * themselves or another address by calling the `delegate` function.
 */
contract GovernanceToken is ERC20, ERC20Permit, ERC20Votes, AccessControl, Pausable {
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /**
     * @param name The name of the token.
     * @param symbol The symbol of the token.
     * @param initialSupply The total amount of tokens to mint to the deployer.
     */
    constructor(
        string memory name,
        string memory symbol,
        uint256 initialSupply
    ) ERC20(name, symbol) ERC20Permit(name) {
        _setupRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _setupRole(PAUSER_ROLE, _msgSender());

        if (initialSupply > 0) {
            _mint(_msgSender(), initialSupply);
        }
    }

    /**
     * @notice Pauses all token transfers.
     * @dev Can only be called by an account with the PAUSER_ROLE.
     */
    function pause() public virtual onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpauses all token transfers.
     * @dev Can only be called by an account with the PAUSER_ROLE.
     */
    function unpause() public virtual onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    /**
     * @dev See {ERC20-_beforeTokenTransfer}.
     * This hook is used to enforce the pausable functionality. All transfers,
     * mints, and burns will be reverted when the contract is paused.
     */
    function _beforeTokenTransfer(address from, address to, uint256 amount)
        internal
        virtual
        override(ERC20)
    {
        super._beforeTokenTransfer(from, to, amount);
        _requireNotPaused();
    }

    /**
     * @dev Overrides the ERC20Votes `_afterTokenTransfer` to enable delegation.
     * This is required for the voting mechanism to work correctly.
     */
    function _afterTokenTransfer(address from, address to, uint256 amount)
        internal
        virtual
        override(ERC20, ERC20Votes)
    {
        super._afterTokenTransfer(from, to, amount);
    }

    /**
     * @dev Overrides the ERC20Votes `_mint` to enable delegation.
     */
    function _mint(address to, uint256 amount)
        internal
        virtual
        override(ERC20)
    {
        super._mint(to, amount);
    }

    /**
     * @dev Overrides the ERC20Votes `_burn` to enable delegation.
     */
    function _burn(address account, uint256 amount)
        internal
        virtual
        override(ERC20)
    {
        super._burn(account, amount);
    }
}


/**
 * @title GovernorDAO
 * @author Your Name
 * @notice The main on-chain governance contract for the DAO. It handles proposal
 * creation, voting, and execution through a TimelockController.
 *
 * This contract is a composition of OpenZeppelin's modular Governor contracts:
 * - Governor: The core governance logic.
 * - GovernorSettings: Manages voting delay, voting period, and proposal threshold.
 * - GovernorCountingSimple: A simple counting module (for, against, abstain).
 * - GovernorVotes: Integrates with an ERC20Votes token for voting power.
 * - GovernorVotesQuorumFraction: Sets the quorum as a percentage of total token supply.
 * - GovernorTimelockControl: Manages proposal execution via a TimelockController.
 */
contract GovernorDAO is
    Governor,
    GovernorSettings,
    GovernorCountingSimple,
    GovernorVotes,
    GovernorVotesQuorumFraction,
    GovernorTimelockControl
{
    /**
     * @param _token The address of the ERC20Votes governance token.
     * @param _timelock The address of the TimelockController contract.
     * @param _name The name of the governor instance.
     * @param _votingDelay The delay (in blocks) from proposal creation to the start of voting.
     * @param _votingPeriod The duration (in blocks) of the voting period.
     * @param _proposalThreshold The minimum number of votes required for an account to create a proposal.
     * @param _quorumFraction The percentage of total voting power (from the token) required for a proposal to be approved. E.g., 4 for 4%.
     */
    constructor(
        IVotes _token,
        TimelockController _timelock,
        string memory _name,
        uint256 _votingDelay,
        uint256 _votingPeriod,
        uint256 _proposalThreshold,
        uint256 _quorumFraction
    )
        Governor(_name)
        GovernorSettings(_votingDelay, _votingPeriod, _proposalThreshold)
        GovernorVotes(_token)
        GovernorVotesQuorumFraction(_quorumFraction)
        GovernorTimelockControl(_timelock)
    {}

    // The following functions are overrides required by Solidity.

    function votingDelay()
        public
        view
        virtual
        override(Governor, GovernorSettings)
        returns (uint256)
    {
        return super.votingDelay();
    }

    function votingPeriod()
        public
        view
        virtual
        override(Governor, GovernorSettings)
        returns (uint256)
    {
        return super.votingPeriod();
    }

    function proposalThreshold()
        public
        view
        virtual
        override(Governor, GovernorSettings)
        returns (uint256)
    {
        return super.proposalThreshold();
    }

    function state(uint256 proposalId)
        public
        view
        virtual
        override(Governor, GovernorTimelockControl)
        returns (ProposalState)
    {
        return super.state(proposalId);
    }

    function proposalEta(uint256 proposalId)
        public
        view
        virtual
        override(Governor, GovernorTimelockControl)
        returns (uint256)
    {
        return super.proposalEta(proposalId);
    }

    function _execute(
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal virtual override(Governor, GovernorTimelockControl) {
        super._execute(proposalId, targets, values, calldatas, descriptionHash);
    }

    function _cancel(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal virtual override(Governor, GovernorTimelockControl) returns (uint256) {
        return super._cancel(targets, values, calldatas, descriptionHash);
    }

    function _executor()
        internal
        view
        virtual
        override(Governor, GovernorTimelockControl)
        returns (address)
    {
        return super._executor();
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        virtual
        override(Governor, GovernorTimelockControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    /**
     * @notice A helper function to create a proposal with only a description, for signaling or simple text-based proposals.
     * @dev This creates a proposal with no executable actions.
     * @param description The markdown-formatted description of the proposal.
     * @return proposalId The ID of the newly created proposal.
     */
    function proposeWithDescription(string memory description) public returns (uint256) {
        address[] memory targets = new address[](0);
        uint256[] memory values = new uint256[](0);
        bytes[] memory calldatas = new bytes[](0);
        return propose(targets, values, calldatas, description);
    }
}


/*
================================================================================================
========================= DEPLOYMENT AND SETUP INSTRUCTIONS ====================================
================================================================================================

This section provides instructions for deploying and configuring the DAO contracts.
The TimelockController contract from OpenZeppelin must also be deployed.

TARGET NETWORK: BaseCAMP (or any EVM-compatible chain)
- Note: Block-based timings (`votingDelay`, `votingPeriod`) are specific to the target chain's block time.
- For Base, block time is ~2 seconds. 1 day = 43,200 blocks.

---------------------------------
-- Part 1: Contract Deployment --
---------------------------------

Deploy the contracts in the following order:

1. GovernanceToken.sol:
   - `name`: "CampDAO Token" (or your choice)
   - `symbol`: "CDT" (or your choice)
   - `initialSupply`: 1000000 * 10**18 (e.g., 1 million tokens with 18 decimals)
   - After deployment, note the contract address (`tokenAddress`).

2. TimelockController.sol (from OpenZeppelin):
   - `minDelay`: 172800 (e.g., 2 days in seconds). This is the minimum delay for proposal execution.
   - `proposers`: `[]` (empty array, will be set later)
   - `executors`: `[]` (empty array, will be set later)
   - `admin`: `address(0)` initially. The deployer's address will be the default admin.
   - After deployment, note the contract address (`timelockAddress`).

3. GovernorDAO.sol:
   - `_token`: The `tokenAddress` from step 1.
   - `_timelock`: The `timelockAddress` from step 2.
   - `_name`: "CampDAO Governor"
   - `_votingDelay`: 1 (e.g., 1 block, ~2 seconds on Base)
   - `_votingPeriod`: 43200 (e.g., ~1 day in blocks on Base)
   - `_proposalThreshold`: 0 (allows anyone with tokens to propose, or set to a value like 1 * 10**18 to prevent spam)
   - `_quorumFraction`: 4 (representing 4% of total supply)
   - After deployment, note the contract address (`governorAddress`).

---------------------------------------
-- Part 2: Role Configuration (Crucial for DAO security and function) --
---------------------------------------

The deployer of the TimelockController is initially the only account with the `TIMELOCK_ADMIN_ROLE`.
This role must be used to configure the DAO and then be renounced/transferred for decentralization.

Execute these transactions using the deployer's account, targeting the `timelockAddress`.

1. Get Role Hashes:
   - PROPOSER_ROLE: `keccak256("PROPOSER_ROLE")`
   - EXECUTOR_ROLE: `keccak256("EXECUTOR_ROLE")`
   - CANCELLER_ROLE: `keccak256("CANCELLER_ROLE")`
   - TIMELOCK_ADMIN_ROLE: `keccak256("TIMELOCK_ADMIN_ROLE")`

2. Grant Roles:
   - Grant the `PROPOSER_ROLE` to the `governorAddress`. Only the Governor will be able to schedule proposals in the Timelock.
     `timelock.grantRole(PROPOSER_ROLE, governorAddress)`
   - Grant the `EXECUTOR_ROLE` to `address(0)`. This allows anyone to execute a proposal once its delay has passed.
     `timelock.grantRole(EXECUTOR_ROLE, address(0))`
   - Grant the `CANCELLER_ROLE` to the `governorAddress`. This allows the Governor to cancel proposals (e.g., if vetoed).
     `timelock.grantRole(CANCELLER_ROLE, governorAddress)`

3. Renounce Admin Role (Decentralization Step):
   - The deployer must renounce the `TIMELOCK_ADMIN_ROLE` to make the Timelock immutable except through DAO governance.
   - **WARNING**: This action is irreversible. Once renounced, only the Timelock itself (via a governance proposal) can make administrative changes.
   - `timelock.renounceRole(TIMELOCK_ADMIN_ROLE, <deployer_address>)`

The DAO is now fully configured and decentralized.

---------------------------------------
-- Part 3: Activating Voting Power --
---------------------------------------

To vote or create proposals, holders of the `GovernanceToken` must delegate their voting power.
They can delegate to themselves or another address.

- To self-delegate, a token holder must call:
  `token.delegate(holder_address)`

This is required because `ERC20Votes` uses a checkpointing system to prevent flash loan attacks,
and delegation is the explicit action that creates the first checkpoint.

================================================================================================
*/
